*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101510;color:#e8e5d7;font-family:'DM Sans',sans-serif;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;min-height:420px;overflow:hidden;background:#1a231c;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 42%,rgba(4,8,6,.45) 100%);z-index:1}.screen-grain{position:absolute;inset:0;z-index:8;pointer-events:none;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.22'/%3E%3C/svg%3E")}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:74px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,13,10,.79),transparent)}.brand{display:flex;align-items:center;gap:12px}.brand-mark{font:900 24px 'Barlow Condensed';letter-spacing:-2px;color:#e4e6d9;border:1px solid rgba(226,223,202,.42);width:43px;height:40px;display:grid;place-items:center;position:relative}.brand-mark span{font-size:10px;color:#c6e96c;position:absolute;right:4px;top:0}.brand b{display:block;font:800 16px 'Barlow Condensed';letter-spacing:2px}.brand small{display:block;font:10px 'DM Mono';letter-spacing:1.55px;color:#a6a99b;margin-top:3px}.top-right{display:flex;align-items:center;gap:19px}.chapter{font:10px 'DM Mono';letter-spacing:1px;color:#bec2b3;display:flex;gap:9px;align-items:center}.live-dot{height:7px;width:7px;background:#cae976;border-radius:100%;display:inline-block;box-shadow:0 0 11px #bde35a}.icon-btn{width:36px;height:36px;border:1px solid rgba(220,225,209,.25);background:#1119148c;border-radius:50%;font-size:14px;cursor:pointer}.hud-left{position:absolute;z-index:2;left:34px;top:98px;width:300px;pointer-events:none}.mission-card{padding:16px 18px 17px;background:linear-gradient(110deg,rgba(13,20,16,.91),rgba(17,24,19,.7));border-left:2px solid #c5e66c;box-shadow:0 8px 26px #05090737}.eyebrow{font:9px 'DM Mono';letter-spacing:1.35px;color:#b8c2ad;display:flex;align-items:center;gap:8px}.eyebrow-line{width:12px;height:1px;background:#c4e46a}.objective-count{margin-left:auto;color:#cce87b}.mission-card h1{font:700 23px/1 'Barlow Condensed';letter-spacing:.3px;margin:12px 0 5px;text-transform:uppercase}.mission-card p{font-size:11px;color:#b2b8ab;margin:0 0 14px;line-height:1.4}.progress-track,.health-track{height:3px;background:#6870645c}.progress-track i,.health-track i{height:100%;display:block;width:0;background:#c8e775;transition:width .25s}.status-row{display:flex;align-items:center;gap:24px;padding:16px 18px;margin-top:7px;background:linear-gradient(110deg,rgba(13,20,16,.78),rgba(17,24,19,.48))}.health-wrap{flex:1}.status-label{font:9px 'DM Mono';letter-spacing:1px;color:#b8c2ad;margin-bottom:7px}.status-label span{float:right;color:#e7ebd8}.health-track{height:4px}.health-track i{width:100%;background:#c9e36a}.infected-counter{display:flex;align-items:center;gap:9px}.infected-counter .skull{font-size:19px;color:#c5e66c}.infected-counter b{font:700 17px 'Barlow Condensed';display:block}.infected-counter small{font:8px 'DM Mono';color:#a7afa0;letter-spacing:1px}.radio-caption{font:9px 'DM Mono';letter-spacing:1px;color:#aeb6a4;margin:11px 0 0 5px;text-shadow:0 1px 5px #000}.radio-caption span{color:#c6e96c;margin-right:6px}.hud-right{position:absolute;z-index:2;right:34px;top:98px;width:190px}.minimap-frame{padding:10px;background:rgba(12,18,14,.79);border:1px solid #b1b8a229;box-shadow:0 8px 24px #0002}.map-title{font:9px 'DM Mono';letter-spacing:1px;display:flex;justify-content:space-between;color:#d8decd;margin:0 1px 8px}.map-title span{font-size:8px;color:#a6ad9e}.minimap-frame canvas{display:block;width:100%;aspect-ratio:1;background:#26352a;border:1px solid #b1b8a22a}.map-legend{font:7px 'DM Mono';color:#acb3a5;display:flex;align-items:center;gap:4px;margin-top:8px;white-space:nowrap}.map-legend i{width:6px;height:6px;border-radius:50%;background:#d9ec9b;margin-left:4px}.map-legend .legend-cache{background:#e8bb64}.map-legend .legend-threat{background:#e87561}.threat-indicator{margin-top:8px;display:flex;align-items:center;justify-content:space-between;padding:9px 10px;background:#101711b8;font:8px 'DM Mono';letter-spacing:.6px;color:#bbc1b2}.threat-bars{display:flex;gap:2px;align-items:end;height:12px}.threat-bars i{width:3px;height:4px;background:#c0d076}.threat-bars i:nth-child(2){height:7px}.threat-bars i:nth-child(3){height:9px}.threat-bars i:nth-child(4){height:12px;opacity:.25}.threat-indicator.active .threat-bars i{background:#ef785e;opacity:1}.weapon-panel{position:absolute;z-index:3;right:34px;bottom:30px;width:300px;height:86px;padding:12px 14px;display:flex;align-items:center;gap:11px;background:linear-gradient(110deg,rgba(13,19,15,.94),rgba(22,28,21,.82));border:1px solid rgba(204,214,185,.15);box-shadow:0 8px 30px #0003}.weapon-icon{width:39px;height:39px;display:grid;place-items:center;border:1px solid #c5e66c61;color:#cee97d;font-size:23px;background:#c5e66c0b}.weapon-copy{min-width:100px}.weapon-copy small{display:block;font:8px 'DM Mono';letter-spacing:.8px;color:#a5ae9e;margin-bottom:4px}.weapon-copy small span{color:#d6e99a}.weapon-copy b{font:700 13px 'Barlow Condensed';letter-spacing:.6px;white-space:nowrap}.ammo{margin-left:auto;display:flex;align-items:baseline;gap:3px}.ammo strong{font:700 26px 'Barlow Condensed'}.ammo span{font:12px 'DM Mono';color:#a8b09f}.ammo i{font-style:normal;color:#e3e5d9}.reload-track{position:absolute;bottom:0;left:0;right:0;height:2px;background:#686d6233}.reload-track i{width:0;height:100%;display:block;background:#d3eb81}.switch-btn{position:absolute;right:9px;top:-25px;border:0;background:#111a14b8;font:8px 'DM Mono';letter-spacing:.4px;padding:5px 8px;color:#bac1b2;cursor:pointer}.switch-btn span{color:#d5ec8a;margin-left:4px}.toast{position:absolute;z-index:5;left:50%;top:23%;transform:translate(-50%,-6px);opacity:0;padding:10px 15px;background:#111a14e8;border:1px solid #c8e77570;font:10px 'DM Mono';letter-spacing:.7px;color:#e4ebd0;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-hint{position:absolute;z-index:3;left:50%;top:68%;transform:translateX(-50%);padding:9px 12px;background:#101711dd;border:1px solid #c5e66c66;font:9px 'DM Mono';letter-spacing:1px;color:#e1e9d1;display:none;pointer-events:none}.interact-hint.show{display:block}.overlay{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(7,12,9,.86) 0%,rgba(7,12,9,.6) 45%,rgba(7,12,9,.16) 100%);transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{width:min(500px,90vw);margin-right:auto;margin-left:8.5%;padding:38px 0 24px}.overlay-kicker{display:flex;align-items:center;gap:10px;font:9px 'DM Mono';letter-spacing:1.6px;color:#b5bcaa}.hero-title{font:800 clamp(57px,8.1vw,94px)/.8 'Barlow Condensed';letter-spacing:-2px;margin:27px 0 22px;color:#eef0e3}.hero-title em{color:#c8e775;font-style:normal}.hero-copy{max-width:380px;color:#c3c6b8;font-size:13px;line-height:1.7;margin:0 0 20px}.story-quote{max-width:370px;border-left:1px solid #c8e7757d;display:flex;gap:12px;padding:4px 0 4px 14px;margin-bottom:24px}.story-quote>span{font:32px Georgia;color:#c8e775;line-height:.8}.story-quote p{font:italic 13px/1.45 'DM Sans';margin:0 0 7px;color:#e1e4d7}.story-quote small{font:8px 'DM Mono';letter-spacing:1px;color:#aab09f}.primary-btn{height:49px;min-width:220px;padding:0 17px;border:0;background:#c8e775;color:#182017;text-align:left;font:800 12px 'Barlow Condensed';letter-spacing:1.5px;cursor:pointer;transition:background .16s,transform .16s}.primary-btn:hover{background:#dbf594;transform:translateY(-2px)}.primary-btn span{float:right;font-size:17px;margin-top:-3px}.controls-note,.mobile-note{font:8px 'DM Mono';letter-spacing:.6px;color:#929b8c;margin-top:24px}.controls-note span{color:#e1e5d6}.controls-note i,.mobile-note i{color:#c8e775;font-style:normal;margin:0 4px}.mobile-note{display:none}.end-card{position:absolute;width:min(420px,86vw);text-align:center;background:#101711ed;border:1px solid #c5e66c52;padding:35px}.end-card.hidden{display:none}.end-card .overlay-kicker{justify-content:center}.end-card h2,.pause-card h2{font:800 44px 'Barlow Condensed';margin:15px 0 5px}.end-card p{font-size:13px;line-height:1.6;color:#b9c0b2;margin-bottom:22px}.pause-overlay{position:absolute;z-index:7;inset:0;display:grid;place-items:center;background:#080d0bcc;backdrop-filter:blur(4px)}.pause-overlay.hidden{display:none}.pause-card{text-align:center}.pause-card small{font:10px 'DM Mono';letter-spacing:2px;color:#c8e775}.pause-card h2{margin-bottom:26px}.touch-controls{display:none;position:absolute;z-index:4;inset:0;pointer-events:none}.stick-zone{pointer-events:auto;position:absolute;bottom:22px;display:flex;flex-direction:column;align-items:center;gap:5px}.move-zone{left:22px}.stick-ring{width:105px;height:105px;border:1px solid #dfe8cf52;border-radius:50%;background:#16201972;display:grid;place-items:center;backdrop-filter:blur(2px)}.stick-knob{width:43px;height:43px;border-radius:50%;background:#c8e77573;border:1px solid #e1f4aaad;box-shadow:0 2px 12px #0005;transform:translate(0,0)}.stick-zone>span{font:8px 'DM Mono';letter-spacing:1px;color:#e2e8d9a8}.touch-actions{pointer-events:none;position:absolute;right:18px;bottom:20px;display:flex;align-items:center;gap:10px}.aim-zone{position:relative;bottom:auto;left:auto;pointer-events:auto;order:4}.aim-zone .stick-ring{width:100px;height:100px}.touch-action{pointer-events:auto;align-self:flex-end;margin-bottom:12px;width:45px;height:45px;border:1px solid #dfe8cf61;border-radius:50%;background:#162019a6;color:#e0e8d2;font-size:19px}.touch-action small{display:block;font:6px 'DM Mono';letter-spacing:.2px}.fire-button{pointer-events:auto;position:absolute;right:31px;bottom:142px;width:62px;height:62px;border-radius:50%;border:1px solid #e8f4c38a;background:#c8e775bd;color:#152015;display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 0 18px #c8e77527}.fire-button span{font-size:21px}.fire-button small{font:7px 'DM Mono';letter-spacing:.7px}.fire-button:active{background:#e0f6a0}
@media(max-width:760px){.topbar{height:58px;padding:0 16px}.brand-mark{width:34px;height:32px;font-size:20px}.brand{gap:9px}.brand b{font-size:14px}.brand small{font-size:8px}.chapter{font-size:8px;letter-spacing:.5px}.top-right{gap:10px}.icon-btn{width:32px;height:32px}.hud-left{left:14px;top:70px;width:min(245px,58vw)}.mission-card{padding:11px 12px 12px}.eyebrow{font-size:7px;letter-spacing:.8px}.mission-card h1{font-size:19px;margin:8px 0 3px}.mission-card p{font-size:9px;margin-bottom:9px}.status-row{padding:10px 12px;gap:15px;margin-top:5px}.status-label{font-size:8px;margin-bottom:5px}.infected-counter{gap:5px}.infected-counter .skull{font-size:15px}.infected-counter b{font-size:14px}.infected-counter small{font-size:7px}.radio-caption{font-size:7px;margin-top:7px}.hud-right{right:12px;top:70px;width:125px}.minimap-frame{padding:7px}.map-title{font-size:7px;margin-bottom:5px}.map-title span{font-size:6px}.map-legend{font-size:6px;gap:2px;margin-top:5px}.map-legend i{width:5px;height:5px}.threat-indicator{padding:6px 7px;font-size:6px;margin-top:5px}.weapon-panel{right:12px;bottom:14px;width:220px;height:67px;padding:8px;gap:7px}.weapon-icon{width:31px;height:31px;font-size:18px}.weapon-copy{min-width:77px}.weapon-copy small{font-size:6px;margin-bottom:3px}.weapon-copy b{font-size:10px}.ammo strong{font-size:21px}.ammo span{font-size:9px}.switch-btn{font-size:7px;top:-21px}.interact-hint{top:61%;font-size:8px}.overlay{background:linear-gradient(90deg,rgba(7,12,9,.88),rgba(7,12,9,.57) 70%,rgba(7,12,9,.26))}.overlay-card{margin-left:7%;width:86vw;padding:15px 0}.hero-title{font-size:clamp(54px,13vw,78px);margin:19px 0 14px}.hero-copy{font-size:11px;max-width:340px;margin-bottom:13px}.story-quote{margin-bottom:17px}.story-quote p{font-size:11px}.controls-note{display:none}.mobile-note{display:block;margin-top:16px;font-size:7px}.primary-btn{height:44px;min-width:194px;font-size:11px}.touch-controls{display:block}.overlay:not(.hidden)~.touch-controls{display:none}}
@media(max-width:500px){.chapter{max-width:122px;line-height:1.35}.hud-right{width:108px;top:68px}.map-legend{font-size:5px}.hud-left{top:68px;width:min(225px,58vw)}.weapon-panel{width:202px;bottom:12px}.weapon-copy{min-width:67px}.weapon-copy b{font-size:9px}.ammo strong{font-size:19px}.touch-actions{right:11px;gap:6px}.aim-zone .stick-ring{width:88px;height:88px}.move-zone{left:12px}.move-zone .stick-ring{width:94px;height:94px}.fire-button{right:20px;bottom:119px;width:55px;height:55px}.touch-action{width:39px;height:39px}.overlay-card{margin-left:6%}.hero-title{font-size:58px}.hero-copy{max-width:290px;font-size:10px}.story-quote{max-width:300px}.story-quote p{font-size:10px}.mobile-note{font-size:6px}}
@media(max-height:520px){.overlay-card{padding:0}.hero-title{font-size:58px;margin:14px 0}.hero-copy{margin-bottom:9px}.story-quote{margin-bottom:12px}.controls-note,.mobile-note{margin-top:11px}.hud-left{top:68px}.hud-right{top:68px}.mission-card p{margin-bottom:7px}.weapon-panel{bottom:8px}.touch-controls .stick-zone{bottom:8px}.fire-button{bottom:113px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('minimap');
  const mapCtx = mapCanvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const WORLD = { w: 2300, h: 1700 };
  const player = { x: 510, y: 880, r: 13, angle: 0, health: 100, speed: 190, invuln: 0 };
  const caches = [{x:720,y:760,found:false},{x:1120,y:1075,found:false},{x:1480,y:680,found:false}];
  const extraction = {x:1880,y:1245};
  const obstacles = [], foliage = [], zombies = [], bullets = [], particles = [];
  let W=innerWidth,H=innerHeight,dpr=1,camera={x:0,y:0}, running=false, paused=false, ended=false, stage=0, kills=0, cacheCount=0;
  let ammo=12,reserve=48,gun=0,reloading=0,fireCooldown=0,spawnTimer=1.5,gameTime=0,toastTimer=0,radioTimer=0,shake=0;
  let mouse={x:W*.6,y:H*.5,down:false}, moveInput={x:0,y:0}, aimInput={x:0,y:0}, touchFire=false, touchAimActive=false;
  const guns=[{name:'SERVICE PISTOL',mag:12,reserve:48,rate:.27,reload:1.15,damage:1,pellets:1,spread:.035,icon:'⌁'},{name:'SAWED-OFF',mag:2,reserve:16,rate:.72,reload:1.35,damage:1,pellets:6,spread:.32,icon:'╱'}];
  const keys=new Set();
  function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  // Deterministic wilderness dressing keeps the map legible and repeatable.
  let seed=72819;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
  for(let i=0;i<470;i++){const x=rand()*WORLD.w,y=rand()*WORLD.h;const nearRoad=Math.abs(y-(850+Math.sin(x*.003)*170))<100;const nearCamp=(x>1660&&y>1090&&x<2070&&y<1400);if(!nearRoad&&!nearCamp)foliage.push({x,y,r:7+rand()*17,dark:rand(),type:rand()})}
  // A scatter of wrecks and abandoned camp objects.
  obstacles.push({x:800,y:850,w:72,h:32,a:-.18,type:'car'},{x:1250,y:810,w:65,h:30,a:.22,type:'car'},{x:1780,y:1140,w:110,h:80,a:0,type:'shed'},{x:1880,y:1245,w:42,h:42,a:0,type:'radio'});
  function worldToScreen(x,y){return {x:x-camera.x+W/2,y:y-camera.y+H/2}}
  function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=2.2}
  function objective(){if(stage===0){$('objective-title').textContent='Scavenge the crash site';$('objective-desc').textContent=`Find ${3-cacheCount} supply cache${cacheCount===2?'':'s'} along the old highway.`;$('objective-count').textContent='01 / 03';$('objective-progress').style.width=`${cacheCount/3*100}%`;}
    else if(stage===1){$('objective-title').textContent='Clear the road';$('objective-desc').textContent='Take out 8 infected to reach the ranger station.';$('objective-count').textContent='02 / 03';$('objective-progress').style.width=`${Math.min(kills/8,1)*100}%`;}
    else{$('objective-title').textContent='Reach the ranger station';$('objective-desc').textContent='Get to the signal tower and call for extraction.';$('objective-count').textContent='03 / 03';$('objective-progress').style.width='100%'} }
  function updateHud(){ $('health-value').textContent=Math.ceil(player.health);$('health-fill').style.width=`${player.health}%`;$('health-fill').style.background=player.health<30?'#e8745c':'#c9e36a';$('kills').textContent=kills;$('ammo-count').textContent=ammo;$('reserve-count').textContent=reserve;$('weapon-name').textContent=gun===0?guns[0].name:gunS();$('weapon-slot').textContent=gun===0?'01':'02';$('weapon-icon').textContent=gun===0?'⌁':'╱';$('reload-fill').style.width=reloading?`${(1-reloading/guns[gun].reload)*100}%`:'0%'; }
  function gunS(){return 'SAWED-OFF'}
  function startGame(){if(ended)reset();running=true;paused=false;$('overlay').classList.add('hidden');$('pause-overlay').classList.add('hidden');toast('RAE // “The caches should be close. Keep your head down.”');radio('RAE // The caches should be close. Keep your head down.');lastTime=performance.now();}
  function reset(){player.x=510;player.y=880;player.health=100;player.invuln=0;zombies.length=0;bullets.length=0;particles.length=0;caches.forEach(c=>c.found=false);cacheCount=0;kills=0;stage=0;ammo=12;reserve=48;gun=0;reloading=0;spawnTimer=1.5;gameTime=0;ended=false;objective();updateHud();$('end-card').classList.add('hidden');$('overlay-card').classList.remove('hidden')}
  function radio(text){const el=$('radio-caption');el.innerHTML='<span>▰</span> '+text;radioTimer=6}
  function endGame(win){ended=true;running=false;$('end-card').classList.remove('hidden');$('end-title').textContent=win?'SIGNAL FOUND':'THE ROAD ENDS HERE';$('end-copy').textContent=win?`Rae got your signal. ${kills} infected left the road behind you. This run isn’t over yet.`:`You made it through ${kills} infected before the road took you. The Cascade will remember.`;$('overlay-card').classList.add('hidden');$('overlay').classList.remove('hidden')}
  function pauseGame(){if(!running||ended)return;paused=!paused;$('pause-overlay').classList.toggle('hidden',!paused);if(!paused)lastTime=performance.now()}
  $('start-btn').addEventListener('click',startGame);$('retry-btn').addEventListener('click',()=>{reset();startGame()});$('pause-btn').addEventListener('click',pauseGame);$('resume-btn').addEventListener('click',pauseGame);
  function switchGun(){if(!running)return;gun=1-gun;reloading=0;toast(gun===0?'SERVICE PISTOL EQUIPPED':'SAWED-OFF EQUIPPED');updateHud()}
  $('switch-btn').addEventListener('click',switchGun);$('swap-touch').addEventListener('pointerdown',e=>{e.preventDefault();switchGun()});$('reload-touch').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
  addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='KeyR')reload();if(e.code==='KeyQ')switchGun();if(e.code==='KeyE')interact();if(e.code==='Escape')pauseGame()});addEventListener('keyup',e=>keys.delete(e.code));
  canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')mouse={...mouse,x:e.clientX,y:e.clientY}});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){mouse.down=true;canvas.setPointerCapture(e.pointerId);shoot()}});canvas.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')mouse.down=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
  function bindStick(zoneId,knobId,onChange){const zone=$(zoneId),knob=$(knobId);let pointer=null,cx=0,cy=0;zone.addEventListener('pointerdown',e=>{e.preventDefault();pointer=e.pointerId;zone.setPointerCapture(pointer);const r=zone.querySelector('.stick-ring').getBoundingClientRect();cx=r.left+r.width/2;cy=r.top+r.height/2;move(e)});zone.addEventListener('pointermove',e=>{if(e.pointerId===pointer){e.preventDefault();move(e)}});const up=e=>{if(e.pointerId===pointer){pointer=null;knob.style.transform='translate(0px,0px)';onChange(0,0,false)}};zone.addEventListener('pointerup',up);zone.addEventListener('pointercancel',up);function move(e){let dx=e.clientX-cx,dy=e.clientY-cy;const max=31,len=Math.hypot(dx,dy);if(len>max){dx=dx/len*max;dy=dy/len*max}knob.style.transform=`translate(${dx}px,${dy}px)`;onChange(dx/max,dy/max,true)}}
  bindStick('touch-controls .move-zone','move-stick',(x,y)=>moveInput={x,y});
  bindStick('touch-controls .aim-zone','aim-stick',(x,y,active)=>{aimInput={x,y};touchAimActive=active;if(active&&Math.hypot(x,y)>.2)player.angle=Math.atan2(y,x)});
  $('fire-touch').addEventListener('pointerdown',e=>{e.preventDefault();touchFire=true;shoot()});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>$('fire-touch').addEventListener(ev,()=>touchFire=false));
