  function update(dt){if(!running||paused||ended)return;gameTime+=dt;fireCooldown=Math.max(0,fireCooldown-dt);if(player.invuln>0)player.invuln-=dt;if(shake>0)shake=Math.max(0,shake-dt*18);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}if(radioTimer>0){radioTimer-=dt;if(radioTimer<=0)radio('LOST SIGNAL')}
    if(reloading>0){reloading-=dt;if(reloading<=0){const need=guns[gun].mag-ammo,take=Math.min(need,reserve);ammo+=take;reserve-=take;reloading=0;updateHud()}}
    let ix=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+moveInput.x;let iy=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+moveInput.y;const il=Math.hypot(ix,iy);if(il>1){ix/=il;iy/=il}player.x=Math.max(20,Math.min(WORLD.w-20,player.x+ix*player.speed*dt));player.y=Math.max(20,Math.min(WORLD.h-20,player.y+iy*player.speed*dt));
