    for(let i=zombies.length-1;i>=0;i--){const z=zombies[i],dx=player.x-z.x,dy=player.y-z.y,d=Math.hypot(dx,dy)||1;z.angle=Math.atan2(dy,dx);z.walk+=dt*8;z.attack-=dt;z.hit=Math.max(0,z.hit-dt);if(d>25){z.x+=dx/d*z.speed*dt;z.y+=dy/d*z.speed*dt}else if(z.attack<=0&&player.invuln<=0){player.health=Math.max(0,player.health-11);player.invuln=.72;z.attack=.9;shake=5;updateHud();if(player.health<=0){endGame(false);return}}}
