    for(let i=particles.length-1;i>=0;i--){particles[i].life-=dt;if(particles[i].life<=0)particles.splice(i,1)}
    const camTargetX=player.x+(Math.cos(player.angle)*50),camTargetY=player.y+(Math.sin(player.angle)*25);camera.x+=(camTargetX-camera.x)*Math.min(1,dt*5);camera.y+=(camTargetY-camera.y)*Math.min(1,dt*5);
    let nearby=null,nd=55;for(const c of caches)if(!c.found){const d=Math.hypot(player.x-c.x,player.y-c.y);if(d<nd){nearby=c;nd=d}}const atExit=stage===2&&Math.hypot(player.x-extraction.x,player.y-extraction.y)<90;$('interact-hint').textContent=nearby?'E  /  TAP  ·  SEARCH CACHE':atExit?'E  /  TAP  ·  RADIO FOR EXTRACTION':'';$('interact-hint').classList.toggle('show',!!nearby||atExit);
